        cmd = ['start', url]
        process = subprocess.Popen(cmd, shell=True)
    elif platform.system() == 'Darwin':
        cmd = ['open', url]
        process = subprocess.Popen(cmd)
    else:
        cmd = ['xdg-open', url]
        process = subprocess.Popen(cmd)
    time.sleep(1)
    return process.poll()

